package br.com.sistemacardapio.catalogo;
import java.math.BigDecimal;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import br.com.sistemacardapio.empresa.*;import br.com.sistemacardapio.tenant.TenantContext;
@Service
public class ProdutoService{
 private final ProdutoRepository repository;private final CategoriaRepository categorias;private final EmpresaRepository empresas;private final TenantContext tenant;
 public ProdutoService(ProdutoRepository repository,CategoriaRepository categorias,EmpresaRepository empresas,TenantContext tenant){this.repository=repository;this.categorias=categorias;this.empresas=empresas;this.tenant=tenant;}
 @Transactional(readOnly=true)public List<Response> listar(){return repository.findAllByEmpresaIdOrderByCategoriaOrdemAscOrdemAscNomeAsc(tenant.empresaIdObrigatoria()).stream().map(Response::from).toList();}
 @Transactional public Response criar(Request r){UUID empresaId=tenant.empresaIdObrigatoria();Categoria c=categorias.findByIdAndEmpresaId(r.categoriaId(),empresaId).orElseThrow(()->new IllegalStateException("Categoria não encontrada"));Empresa e=empresas.findById(empresaId).orElseThrow();Produto p=new Produto(e,c,r.nome(),r.descricao(),r.codigoInterno(),r.preco(),r.ordem());p.definirRegraPreco(r.regraPreco());return Response.from(repository.save(p));}
 @Transactional public Response atualizar(UUID id,Request r){UUID empresaId=tenant.empresaIdObrigatoria();Produto p=repository.findByIdAndEmpresaId(id,empresaId).orElseThrow(()->new IllegalStateException("Produto não encontrado"));Categoria c=categorias.findByIdAndEmpresaId(r.categoriaId(),empresaId).orElseThrow(()->new IllegalStateException("Categoria não encontrada"));p.atualizar(c,r.nome(),r.descricao(),r.codigoInterno(),r.preco(),r.ordem(),r.ativo(),r.disponivel());p.definirRegraPreco(r.regraPreco());return Response.from(p);}
 @Transactional public void inativar(UUID id){UUID empresaId=tenant.empresaIdObrigatoria();Produto p=repository.findByIdAndEmpresaId(id,empresaId).orElseThrow(()->new IllegalStateException("Produto não encontrado"));p.atualizar(p.getCategoria(),p.getNome(),p.getDescricao(),p.getCodigoInterno(),p.getPreco(),p.getOrdem(),false,p.isDisponivel());}
 public record Request(@jakarta.validation.constraints.NotNull UUID categoriaId,@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=160)String nome,@jakarta.validation.constraints.Size(max=2000)String descricao,@jakarta.validation.constraints.Size(max=80)String codigoInterno,@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.PositiveOrZero BigDecimal preco,@jakarta.validation.constraints.PositiveOrZero int ordem,boolean ativo,boolean disponivel,String regraPreco){}
 public record Response(UUID id,UUID categoriaId,String categoriaNome,String nome,String descricao,String codigoInterno,BigDecimal preco,UUID imagemArquivoId,int ordem,boolean ativo,boolean disponivel,String regraPreco){static Response from(Produto p){return new Response(p.getId(),p.getCategoria().getId(),p.getCategoria().getNome(),p.getNome(),p.getDescricao(),p.getCodigoInterno(),p.getPreco(),p.getImagemArquivo()==null?null:p.getImagemArquivo().getId(),p.getOrdem(),p.isAtivo(),p.isDisponivel(),p.getRegraPreco());}}
}
